Here's the component and accompanying reducer. This example includes a basic shopping cart with cart items displayed and a "Checkout" button that increments the checkout count and adds a success message when clicked.

```jsx
// Cart.js
import React from'react';
import { useSelector, useDispatch } from'react-redux';
import { incrementCheckout, clearCart } from './cartSlice';
import { selectCartItems, selectCheckoutCount, selectHasCartSuccess } from './cartSelectors';
import Item from './Item';

const Cart = () => {
  const cartItems = useSelector(selectCartItems);
  const checkoutCount = useSelector(selectCheckoutCount);
  const hasCartSuccess = useSelector(selectHasCartSuccess);

  const dispatch = useDispatch();

  const handleCheckoutClick = () => dispatch(incrementCheckout());
  const handleClearCartClick = () => dispatch(clearCart());

  return (
    <div>
      <h2>Cart Items ({cartItems.length})</h2>
      <ul>
        {cartItems.map((item, index) => (
          <Item key={index} item={item} />
        ))}
      </ul>
      <p>Checkout Count: {checkoutCount}</p>
      <button onClick={handleCheckoutClick}>Checkout</button>
      {hasCartSuccess && <p>Checkout successful!</p>}
      <button onClick={handleClearCartClick}>Clear Cart</button>
    </div>
  );
};

export default Cart;
```

