import { createSlice } from '@reduxjs/toolkit';
import { cartItemsFromStorage, setCartItemsInStorage } from './localStorage';

const initialState = cartItemsFromStorage();

export const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addItem(state, action) {
      state.push(action.payload);
      setCartItemsInStorage(state);
    },
    removeItem(state, action) {
      const index = state.findIndex((item) => item.id === action.payload.id);
      if (index >= 0) {
        state.splice(index, 1);
        setCartItemsInStorage(state);
      }
    },
    incrementCheckout(state) {
      state.checkoutCount = state.checkoutCount + 1;
    },
    clearCart(state) {
      state.items = [];
      state.checkoutCount = 0;
      setCartItemsInStorage(state);
    },
  },
});

