Here's a Cart component with a small Redux Toolkit setup for demonstration purposes. This is a relatively simple e-commerce cart that accepts products from the `cartSlice` reducer and shows items in the cart with quantity and totals.
```jsx
import React, { useState } from'react';
import { useSelector, useDispatch } from'react-redux';
import { incrementQuantity, decrementQuantity, removeItem } from './cartSlice';
import shoppingCartIcon from './shopping-cart-icon.svg';

const Cart = () => {
  const dispatch = useDispatch();
  const { cart } = useSelector((state) => state.cartSlice);

  const [searchQuery, setSearchQuery] = useState('');

  const filteredProducts = cart.filter((product) =>
    product.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const totalItems = filteredProducts.reduce((acc, product) => acc + product.quantity, 0);
  const total = filteredProducts.reduce(
    (acc, product) => acc + product.price * product.quantity,
    0
  );

  return (
    <div className="cart">
      <h2>Shopping Cart</h2>
      <section>
        <img src={shoppingCartIcon} alt="Shopping cart icon" />
        <ul>
          {filteredProducts.map((product) => (
            <li key={product.id}>
              <span>
                {product.name} x {product.quantity}
              </span>
              <button onClick={() => dispatch(decrementQuantity(product.id))}>
                -
              </button>
              <button onClick={() => dispatch(incrementQuantity(product.id))}>
                +
              </button>
              <button onClick={() => dispatch(removeItem(product.id))}>
                remove
              </button>
              <span> Total: ${product.price * product.quantity}</span>
            </li>
          ))}
        </ul>
        <h3>Total items: {totalItems}</h3>
        <h3>Total: ${total.toFixed(2)}</h3>
        <form>
          <input
            type="search"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search items in cart"
          />
        </form>
      </section>
    </div>
  );
};

export default Cart;
```

