import React from'react';
import { useSelector, useDispatch } from'react-redux';
import { addItem, removeItem, reduceItem } from './cartSlice';
import { CartItem } from './CartItem';

const ShoppingCart = () => {
  const items = useSelector((state) => state.cart.items);
  const dispatch = useDispatch();

  const handleRemove = (id) => dispatch(removeItem(id));
  const handleReduce = (id) => dispatch(reduceItem(id));
  const handleAdd = (item) => dispatch(addItem(item));

  return (
    <div className="cart">
      <header>
        <h1>Shopping Cart</h1>
      </header>
      <ul>
        {items.map((item) => (
          <CartItem
            key={item.id}
            {...item}
            onRemove={handleRemove}
            onReduce={handleReduce}
            onAdd={handleAdd}
          />
        ))}
      </ul>
      <footer>
        <ul>
          <li>Total:</li>
          <li>{items.reduce((acc, item) => acc + item.price * item.quantity, 0)}</li>
        </ul>
      </footer>
    </div>
  );
};
```
